"""Generate RQ1 figures: LaTeX table + Top-1 Venn diagram."""
import json
import pandas as pd
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from venn import venn
from pathlib import Path
import argparse


OUT_DIR = Path(__file__).parent / "outputs"
PROJECT_ORDER = ["Chart", "Closure", "Lang", "Math", "Time"]
TOOL_ORDER = ["ProbeFL", "PingFL", "AutoFL", "Ochiai"]
TOOL_COLORS = {
    "ProbeFL": "#2196F3",
    "PingFL": "#FF9800",
    "AutoFL": "#4CAF50",
    "Ochiai": "#9C27B0",
}


def load_summary(policy="common"):
    """Load the summary CSV generated by run_rq1.py."""
    path = OUT_DIR / f"rq1_summary_{policy}.csv"
    return pd.read_csv(path)


def load_per_bug(policy="common"):
    """Load the per-bug merged CSV."""
    path = OUT_DIR / f"rq1_merged_per_bug_{policy}.csv"
    return pd.read_csv(path)


def generate_latex_table(summary_df, policy="common"):
    """Print a LaTeX-formatted RQ1 results table."""
    # Pivot: rows=project, columns=tool x metric
    tools = [t for t in TOOL_ORDER if t in set(summary_df["tool"])]

    # Build header
    header = "\\begin{table*}[t]\n"
    header += "\\caption{Method-level FL effectiveness on the unified evaluation set.}\n"
    header += "\\label{tab:rq1_results}\n"
    header += "\\centering\n"
    header += "\\resizebox{\\textwidth}{!}{%\n"
    header += "\\begin{tabular}{@{}l c"

    for t in tools:
        header += " | cccc"
    header += "@{}}\n"
    header += "\\toprule\n"

    # Multi-row header
    header += "\\multirow{2}{*}{\\textbf{Project}} & \\multirow{2}{*}{\\textbf{Total}}"
    for t in tools:
        header += f"\n& \\multicolumn{{4}}{{c}}{{\\textbf{{{t}}}}}"
    header += "\\\\\n"

    header += "\\cmidrule(lr){3-6}\\cmidrule(lr){7-10}\\cmidrule(lr){11-14}\\cmidrule(lr){15-18}\n"
    header += "& & \\textbf{Top-1} & \\textbf{Top-3} & \\textbf{Top-5} & \\textbf{Top-10}"
    header += " & \\textbf{Top-1} & \\textbf{Top-3} & \\textbf{Top-5} & \\textbf{Top-10}"
    header += " & \\textbf{Top-1} & \\textbf{Top-3} & \\textbf{Top-5} & \\textbf{Top-10}"
    header += " & \\textbf{Top-1} & \\textbf{Top-3} & \\textbf{Top-5} & \\textbf{Top-10}"
    header += "\\\\\n"
    header += "\\midrule\n"

    rows = []
    for proj in PROJECT_ORDER + ["Overall"]:
        proj_rows = summary_df[summary_df["project"] == proj]
        if proj == "Overall":
            row = f"\\textbf{{{proj}}}"
        else:
            row = proj

        # Total
        total_val = int(proj_rows.iloc[0]["total"]) if len(proj_rows) > 0 else 0
        row += f" & {total_val}"

        for t in tools:
            t_row = proj_rows[proj_rows["tool"] == t]
            if t_row.empty:
                row += " & -- & -- & -- & --"
                continue
            r = t_row.iloc[0]
            row += f" & {int(r['top1'])} & {int(r['top3'])} & {int(r['top5'])} & {int(r['top10'])}"

        row += "\\\\\n"

        if proj == "Time":
            row += "\\midrule\n"

        rows.append(row)

    body = "".join(rows)
    footer = "\\bottomrule\n"
    footer += "\\end{tabular}%\n"
    footer += "}\n"
    footer += "\\end{table*}\n"

    latex = header + body + footer
    print(latex)

    # Save
    out_path = OUT_DIR / f"rq1_table_{policy}.tex"
    out_path.write_text(latex, encoding="utf-8")
    print(f"[Saved] {out_path}")

    return latex


def generate_venn(per_bug_df, policy="common"):
    """Generate a 4-set Venn diagram of Top-1 hits using the `venn` library."""
    tools = TOOL_ORDER

    hit_sets = {}
    for tool in tools:
        g = per_bug_df[(per_bug_df["tool"] == tool) & (per_bug_df["top1"] == 1)]
        hit_sets[tool] = set(g["bug_name"].tolist())
        print(f"{tool} Top-1: {len(hit_sets[tool])}")

    # Unique hits per tool
    for t in tools:
        others = set()
        for ot in tools:
            if ot != t:
                others |= hit_sets[ot]
        unique = hit_sets[t] - others
        print(f"{t} unique: {len(unique)}")

    # Save membership data
    all_bugs = sorted(set(per_bug_df["bug_name"].tolist()))
    rows = []
    for bug in all_bugs:
        row = {"bug_name": bug}
        membership = []
        for tool in tools:
            hit = bug in hit_sets[tool]
            row[tool] = int(hit)
            if hit:
                membership.append(tool)
        row["membership"] = "&".join(membership) if membership else "None"
        rows.append(row)

    membership_df = pd.DataFrame(rows)
    membership_path = OUT_DIR / f"rq1_top1_membership_{policy}.csv"
    membership_df.to_csv(membership_path, index=False, encoding="utf-8-sig")
    print(f"[Saved] {membership_path}")

    # Combination counts
    combo_counts = (
        membership_df.groupby("membership").size()
        .reset_index(name="count").sort_values("count", ascending=False)
    )
    combo_path = OUT_DIR / f"rq1_top1_combo_counts_{policy}.csv"
    combo_counts.to_csv(combo_path, index=False, encoding="utf-8-sig")
    print(combo_counts.to_string(index=False))
    print(f"[Saved] {combo_path}")

    # Draw 4-set Venn
    try:
        fig = plt.figure(figsize=(3.55, 3.25))
        venn(hit_sets)
        ax = plt.gca()

        old_legend = ax.get_legend()
        if old_legend is not None:
            handles = getattr(old_legend, "legend_handles", None)
            if handles is None:
                handles = old_legend.legendHandles
            labels = [t.get_text() for t in old_legend.get_texts()]
            old_legend.remove()
            ax.legend(
                handles, labels,
                ncol=len(labels),
                loc="upper center",
                bbox_to_anchor=(0.5, 0.85),
                bbox_transform=ax.transAxes,
                fontsize=12.0,
                frameon=False,
                handlelength=1.0,
                handletextpad=0.35,
                columnspacing=0.85,
                borderaxespad=0.0,
                labelspacing=0.1,
            )

        fig_path = OUT_DIR / f"rq1_top1_venn_{policy}.pdf"
        plt.savefig(fig_path, bbox_inches="tight", pad_inches=0.01)
        plt.close()
        print(f"[Saved] {fig_path}")

    except Exception as e:
        print(f"\n[WARN] Could not draw 4-set Venn: {e}")
        print("Install: pip install venn")


def main():
    parser = argparse.ArgumentParser(description="Generate RQ1 figures.")
    parser.add_argument("--policy", default="common",
                        choices=["common", "probefl_ref", "union"])
    args = parser.parse_args()

    summary = load_summary(args.policy)
    per_bug = load_per_bug(args.policy)

    print("=" * 60)
    print("LaTeX Table")
    print("=" * 60)
    generate_latex_table(summary, args.policy)

    print("\n" + "=" * 60)
    print("Top-1 Venn Diagram")
    print("=" * 60)
    generate_venn(per_bug, args.policy)


if __name__ == "__main__":
    main()
